page.script:
// 触发事件
function CrrHandler(t) {
	// 保存&更新事件
	if (t.id == "save") {
		var formpanel = Ext.getCmp("priceSchemeForm").getForm();
		if (formpanel.isValidCux()) {
			var gridpanel = Ext.getCmp("priceSchemeItemList");
			var gridpanelData = gridpanel.getStore().getData();
			if (gridpanel.operateArray.length === 0 && gridpanelData.length === 0) {
				Ext.MessageBox.alert("提示", "请新增定价方案明细！");
				return false;
			}
			var data = formpanel.getValues();
			data.itemAddList = gridpanel.operateArray;
			var url = "/webapi/marketing/priceScheme/add";
			if (data.id != null && data.id != "") {
				url = "/webapi/marketing/priceScheme/edit";
			}
			post(url, data, function(res) {
				Ext.MessageBox.alert("提示", res.msg);
				Ext.getCmp('priceSchemeListNew').getStore().load();
				Ext.getCmp('priceSchemeFormWin').close();
			});
		}
	}
	// 明细新增事件
	if (t.id == "itemNew") {
		handleRoute("priceSchemeItemForm");
	}
	// 明细删除事件
	if (t.id == "itemDelete") {
		var records = Ext.getCmp("priceSchemeItemList").getSelectionModel().getSelection();
		if (records.length < 1) {
			Ext.MessageBox.alert("提示", "请选择一行进行删除!");
			return false;
		}
		handleDelConfirm("/webapi/marketing/priceScheme/item/delete", records, Ext.getCmp("priceSchemeItemList"));
	}
}
// 产品分类赋值
function setProductClass(data) {
	Ext.getCmp("priceSchemeForm").getForm().findField("productClassNo").setValue(data.productClassNo);
}
// 获取产品分类值
function getProductClass() {
	var form = Ext.getCmp("priceSchemeForm").getForm();
	var data = {
		productClassNo: form.findField("productClassNo").getValue()
	}
	return data;
}
// 重写加载事件
Ext.getCmp('priceSchemeItemList').getStore().on('load', function(store) {
	var panel = Ext.getCmp('priceSchemeItemList');
	store.add(panel.operateArray);
	panel.down('pagingtoolbarcustom').updatePagingInfo(store.getCount(), store.pageSize);
});
